// Bundles the tax, plan and household engines into the single script the native
// app loads into JavaScriptCore (`apps/ios/Nest/Engine/nest-engines.js`). The
// output is committed, so the Xcode build needs no Node toolchain; `--check`
// fails CI when it has drifted from the sources.
//
//   node packages/js-core/scripts/bundle.js          # rewrite the bundle
//   node packages/js-core/scripts/bundle.js --check  # assert it is in sync

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { build } from 'esbuild'

const HERE = dirname(fileURLToPath(import.meta.url))
const ROOT = join(HERE, '..', '..', '..')
export const BUNDLE_PATH = join(ROOT, 'apps', 'ios', 'Nest', 'Engine', 'nest-engines.js')

const HEADER =
  '// Generated by packages/js-core/scripts/bundle.js from @nest/tax, @nest/plan and\n' +
  '// @nest/household. Do not edit; run `pnpm bundle:js-core`.\n'

/** The bundle's text: one IIFE script that installs `globalThis.NestEngine`. */
export async function bundledText() {
  const { outputFiles } = await build({
    entryPoints: [join(HERE, '..', 'src', 'bundle.ts')],
    absWorkingDir: ROOT,
    bundle: true,
    write: false,
    format: 'iife',
    platform: 'neutral',
    mainFields: ['module', 'main'],
    // BigInt and everything else the engines use runs in JavaScriptCore on iOS 17 / macOS 15.
    target: 'es2022',
    minify: true,
    legalComments: 'none',
    charset: 'utf8',
    logLevel: 'warning',
  })
  return HEADER + outputFiles[0].text
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const text = await bundledText()
  if (process.argv.includes('--check')) {
    const actual = existsSync(BUNDLE_PATH) ? readFileSync(BUNDLE_PATH, 'utf8') : null
    if (actual !== text) {
      console.error('The JavaScriptCore engine bundle is out of date; run `pnpm bundle:js-core`.')
      process.exit(1)
    }
    console.log('The JavaScriptCore engine bundle is in sync.')
  } else {
    mkdirSync(dirname(BUNDLE_PATH), { recursive: true })
    writeFileSync(BUNDLE_PATH, text)
    console.log(`Wrote ${BUNDLE_PATH}`)
  }
}
